    """
    解析逗号分隔的整数和递增闭区间，保留原来的顺序和重复数值。
    允许空白和负整数。
    例如：parse_ranges('-3--1, 2, 4-5') == [-3,-2,-1,2,4,5]
    空字符串返回 []。
    """
    if not text:
        return []

    result = []
    i = 0
    n = len(text)

    while i < n:
        # 跳过空白字符
        while i < n and text[i] in ' \t\n\r':
            i += 1
        if i >= n:
            break

        # 遇到逗号，开始处理一个区间
        comma_pos = i
        while i < n and text[i] != ',':
            i += 1

        # 处理逗号后的内容
        if i < n:
            # 处理整数
            while i < n and text[i].isdigit():
                result.append(int(text[i]))
                i += 1

            # 处理递增闭区间
            while i < n and text[i] in '+-':
                if text[i] == '-':
                    # 遇到负号，从下一个非数字字符开始
                    start = i + 1
                    while start < n and text[start].isdigit():
                        start += 1
                    # 处理负区间
                    if start < n:
                        start_int = int(text[start])
                        # 检查是否连续递增
                        if start_int > 0:
                            # 检查是否连续递增
                            for j in range(start, start_int):
                                if text[j] == text[j + 1]:
                                    # 连续递增，加入结果
                                    result.append(text[j])
                                    i = j + 1
                                    break
                                else:
                                    i = j + 1
                            # 如果区间结束，继续处理下一个区间
                            if start_int < n:
                                i = start_int + 1
                            else:
                                break
                        else:
                            # 负区间，跳过
                            i = start + 1
                    else:
                        i = comma_pos + 1
                else:
                    # 遇到正号，从下一个非数字字符开始
                    start = i + 1
                    while start < n and text[start].isdigit():
                        start += 1
                    # 处理正区间
                    if start < n:
                        start_int = int(text[start])
                        # 检查是否连续递增
                        if start_int > 0:
                            # 检查是否连续递增
                            for j in range(start, start_int):
                                if text[j] == text[j + 1]:
                                    # 连续递增，加入结果
                                    result.append(text[j])
                                    i = j + 1
                                    break
                                else:
                                    i = j + 1
                            # 如果区间结束，继续处理下一个区间
                            if start_int < n:
                                i = start_int + 1
                            else:
                                break
                        else:
                            # 正区间，跳过
                            i = start + 1
                    else:
                        i = comma_pos + 1

    return result',namespace)
